<?php require __DIR__.'/_guard.php';if($_SERVER['REQUEST_METHOD']==='POST'){Security::verify();db()->prepare('INSERT INTO suppliers(name,phone,email,address) VALUES(?,?,?,?)')->execute([$_POST['name'],$_POST['phone'],$_POST['email'],$_POST['address']]);} $rows=db()->query('SELECT * FROM suppliers ORDER BY id DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/admin.css"></head><body><main><a href="/admin/">← Dashboard</a><h1>Suppliers</h1><form method="post"><?=Security::field()?><input name="name" placeholder="Supplier name" required><input name="phone" placeholder="Phone"><input name="email" placeholder="Email"><input name="address" placeholder="Address"><button>Add supplier</button></form><?php foreach($rows as $r):?><p><?=e($r['name'])?> · <?=e($r['phone'])?></p><?php endforeach;?></main></body></html>